import type { PDFDocumentLoadingTask, PDFDocumentProxy, RenderTask } from "pdfjs-dist";
import { useEffect, useRef, useState } from "react";

/** Render the actual generated bytes. No browser PDF plug-in or iframe required. */
export function PdfPreview({ bytes }: { bytes: Uint8Array }) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [zoom, setZoom] = useState(1);
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading");
  useEffect(() => {
    let disposed = false;
    let loading: PDFDocumentLoadingTask | undefined;
    let document: PDFDocumentProxy | undefined;
    let render: RenderTask | undefined;
    setStatus("loading");
    (async () => {
      const pdfjs = await import("pdfjs-dist");
      const { default: workerUrl } = await import("pdfjs-dist/build/pdf.worker.min.mjs?url");
      if (disposed) return;
      pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;
      loading = pdfjs.getDocument({ data: bytes.slice() });
      document = await loading.promise;
      if (disposed) return;
      setPages(document.numPages);
      const pdfPage = await document.getPage(Math.min(page, document.numPages));
      if (disposed || !canvas.current) return;
      const node = canvas.current;
      const viewport = pdfPage.getViewport({ scale: 1.4 * zoom });
      node.width = viewport.width;
      node.height = viewport.height;
      render = pdfPage.render({ canvas: node, viewport });
      await render.promise;
      if (!disposed) setStatus("ready");
    })().catch(() => {
      if (!disposed) setStatus("error");
    });
    return () => {
      disposed = true;
      render?.cancel();
      void loading?.destroy();
    };
  }, [bytes, page, zoom]);
  return (
    <section className="j-pdf-preview" aria-label="공식 원본 양식에 입력한 데모 신청서">
      <div className="j-row j-wrap">
        <b>공식 양식 미리보기</b>
        <div className="j-row">
          <button
            className="j-small"
            type="button"
            disabled={zoom === 1}
            onClick={() => setZoom(1)}
          >
            화면 맞춤
          </button>
          <button
            className="j-small"
            type="button"
            disabled={zoom === 1.6}
            onClick={() => setZoom(1.6)}
          >
            확대
          </button>
        </div>
      </div>
      {status === "loading" && <output>문서 페이지를 불러오고 있어요…</output>}
      {status === "error" && (
        <p role="alert" className="j-error">
          이 환경에서 문서를 표시하지 못했어요. 아래 PDF 다운로드로 내용을 확인해 주세요.
        </p>
      )}
      <div className="j-pdf-pages" style={{ overflow: "auto" }}>
        <canvas
          ref={canvas}
          role="img"
          aria-label={`신청서 ${page}페이지`}
          style={{
            width: zoom === 1 ? "100%" : "160%",
            display: status === "ready" ? "block" : "none",
          }}
        />
      </div>
      {pages > 1 && (
        <div className="j-row">
          <button
            className="j-secondary"
            type="button"
            disabled={page === 1}
            onClick={() => setPage(page - 1)}
          >
            앞 페이지
          </button>
          <span>
            {page} / {pages}
          </span>
          <button
            className="j-secondary"
            type="button"
            disabled={page === pages}
            onClick={() => setPage(page + 1)}
          >
            다음 페이지
          </button>
        </div>
      )}
    </section>
  );
}
